use vdevice::Client;fn main(){let mut c=Client::new().unwrap();assert!(c.call("check",serde_json::json!({})).is_err());if std::env::args().len()>1{let d=c.call("connect",serde_json::json!({"descriptors":[{"data":[1,2,3]}]})).unwrap();assert_eq!(d["device_id"],"9223372036854775809");c.call("send",serde_json::json!({"handle":d["handle"],"endpoint":129,"data":[0,1,255]})).unwrap();}c.close().unwrap();}
